      const r = app.view.canvas.getBoundingClientRect();
      files.forEach((f, i) => insertImageFile(app, f, { sx: e.clientX - r.left + 24 * i, sy: e.clientY - r.top + 24 * i }, app.textBoxes ? "box" : "background"));
